"use client"

import { Bar, BarChart, CartesianGrid, XAxis, YAxis } from "recharts"

import {
  Card,
  CardContent,
  CardDescription,
  CardFooter,
  CardHeader,
  CardTitle,
} from "./card"
import {
  ChartContainer,
  ChartLegend,
  ChartLegendContent,
  ChartTooltip,
  ChartTooltipContent,
  type ChartConfig,
} from "./chart"

/** One sentence on what the chart shows, the field every chart in the set exports. */
export const description = "A composition chart that shows each channel's percent of the whole, month by month"

// Raw visits per month. Each row becomes shares that sum to 100, so every
// design system's default tooltip shows a share, not a count.
const visits = [
  { month: "January", search: 5520, direct: 2880, referral: 1200, social: 1440, email: 600 },
  { month: "February", search: 5310, direct: 2950, referral: 1390, social: 1500, email: 660 },
  { month: "March", search: 4980, direct: 3020, referral: 1610, social: 1480, email: 710 },
  { month: "April", search: 4760, direct: 3100, referral: 1840, social: 1530, email: 790 },
  { month: "May", search: 4500, direct: 3150, referral: 2050, social: 1560, email: 840 },
  { month: "June", search: 4310, direct: 3240, referral: 2280, social: 1610, email: 920 },
]

const channels = ["search", "direct", "referral", "social", "email"] as const

const chartData = visits.map((row) => {
  const total = channels.reduce((sum, channel) => sum + row[channel], 0)
  const share = (channel: (typeof channels)[number]) => Math.round((row[channel] / total) * 1000) / 10
  return {
    month: row.month,
    search: share("search"),
    direct: share("direct"),
    referral: share("referral"),
    social: share("social"),
    email: share("email"),
  }
})

const chartConfig = {
  search: {
    label: "Search",
    color: "var(--chart-1)",
  },
  direct: {
    label: "Direct",
    color: "var(--chart-2)",
  },
  referral: {
    label: "Referral",
    color: "var(--chart-3)",
  },
  social: {
    label: "Social",
    color: "var(--chart-4)",
  },
  email: {
    label: "Email",
    color: "var(--chart-5)",
  },
} satisfies ChartConfig

const first = chartData[0]
const last = chartData[chartData.length - 1]

/** A composition chart of five channels' share of visits, January to June, stacked to 100%. */
export function ChartComposition() {
  return (
    <Card>
      <CardHeader>
        <CardTitle>Composition Chart</CardTitle>
        <CardDescription>Percent of visits by channel, January to June</CardDescription>
      </CardHeader>
      <CardContent>
        <ChartContainer config={chartConfig}>
          <BarChart accessibilityLayer data={chartData} margin={{ left: 4 }}>
            <CartesianGrid vertical={false} />
            <XAxis
              dataKey="month"
              tickLine={false}
              tickMargin={10}
              axisLine={false}
              tickFormatter={(value: string) => value.slice(0, 3)}
            />
            <YAxis
              tickLine={false}
              axisLine={false}
              width={36}
              // Rounded shares can sum to 100.1; the axis still ends at 100.
              domain={[0, 100]}
              allowDataOverflow
              ticks={[0, 25, 50, 75, 100]}
              tickFormatter={(value: number) => `${value}%`}
            />
            <ChartTooltip cursor={false} content={<ChartTooltipContent />} />
            {channels.map((channel, index) => (
              <Bar
                key={channel}
                dataKey={channel}
                stackId="share"
                fill={`var(--color-${channel})`}
                // Round only the outer ends of the stack, so the bar reads as one whole.
                radius={index === 0 ? [0, 0, 4, 4] : index === channels.length - 1 ? [4, 4, 0, 0] : 0}
              />
            ))}
            <ChartLegend content={<ChartLegendContent />} />
          </BarChart>
        </ChartContainer>
      </CardContent>
      {first && last ? (
        <CardFooter className="flex-col items-start gap-2 text-sm">
          <div className="leading-none font-medium">
            Search fell from {first.search}% to {last.search}% of visits
          </div>
          <div className="leading-none text-muted-foreground">
            Referral grew from {first.referral}% to {last.referral}%
          </div>
        </CardFooter>
      ) : null}
    </Card>
  )
}
